// Inventory uses discrete card selection, then an explicit action selection.
let inventoryNav={open:false,index:0,actions:false,actionIndex:0,direction:null,repeat:0};
function inventoryCards(){return Array.from($('card').querySelectorAll('.equipment > .gearcard,.baggrid > .gearcard'))}
function inventoryActions(){let source=$('card').querySelector('[data-inventory-detail="'+inventoryNav.index+'"]')||inventoryCards()[inventoryNav.index];return Array.from(source?.querySelectorAll('button:not(:disabled)')||[])}
function inventoryHint(){let el=$('inventoryPadHint');if(el)el.textContent=inventoryNav.actions?'A：決定　B：アイテムへ戻る':'十字キー：選択　A：操作　B：閉じる　ZL：装備　ZR：鞄'}
function inventoryFocus(){let cards=inventoryCards();if(!cards.length)return;inventoryNav.index=clamp(inventoryNav.index,0,cards.length-1);cards.forEach((el,i)=>{el.classList.toggle('inventory-selected',i===inventoryNav.index);el.setAttribute('aria-current',i===inventoryNav.index?'true':'false');el.classList.toggle('inventory-actions',i===inventoryNav.index&&inventoryNav.actions)});inventoryShowDetail();let card=cards[inventoryNav.index],target=card;if(inventoryNav.actions){let actions=inventoryActions();inventoryNav.actionIndex=clamp(inventoryNav.actionIndex,0,Math.max(0,actions.length-1));target=actions[inventoryNav.actionIndex]||card}if(typeof menuReveal==='function')menuReveal(card);target.focus({preventScroll:true});if(typeof menuReveal==='function')menuReveal(target);padCursor.active=false;inventoryHint()}
function inventoryNextIndex(rects,current,dx,dy){let from=rects[current];if(!from)return 0;let cx=from.left+from.width/2,cy=from.top+from.height/2,best=current,score=Infinity;rects.forEach((r,i)=>{if(i===current)return;let x=r.left+r.width/2-cx,y=r.top+r.height/2-cy,along=x*dx+y*dy,across=Math.abs(x*dy-y*dx);if(along<=2)return;let overlap=dx?Math.min(from.top+from.height,r.top+r.height)-Math.max(from.top,r.top):Math.min(from.left+from.width,r.left+r.width)-Math.max(from.left,r.left);let value=(overlap>2?0:100000)+along+across*3;if(value<score){score=value;best=i}});return best}
function inventoryMove(dx,dy){if(inventoryNav.actions){let actions=inventoryActions();if(actions.length)inventoryNav.actionIndex=clamp(inventoryNav.actionIndex+(dx||dy),0,actions.length-1)}else{let cards=inventoryCards();inventoryNav.index=inventoryNextIndex(cards.map(el=>el.getBoundingClientRect()),inventoryNav.index,dx,dy)}inventoryFocus();playSound('ui')}
function inventoryAccept(){if(!inventoryNav.actions){inventoryNav.actions=true;inventoryNav.actionIndex=0;inventoryFocus()}else{let action=inventoryActions()[inventoryNav.actionIndex];if(action&&!action.disabled)action.click()}playSound('ui')}
function inventoryBack(){let help=$('gearHelp');if(help&&!help.hidden){toggleGearHelp($('gearHelpToggle'));inventoryFocus();return}if(inventoryNav.actions){inventoryNav.actions=false;inventoryFocus()}else closePanel()}
function inventorySetup(){inventoryNav.actions=false;inventoryNav.direction=null;inventoryNav.repeat=0;let cards=inventoryCards();cards.forEach((el,i)=>{el.tabIndex=0;el.setAttribute('aria-label',(i<GEAR_SLOTS.length?'装備中：':'鞄：')+(el.querySelector('strong')?.textContent||'アイテム'));el.addEventListener('click',e=>{if(e.target.closest('button'))return;inventoryNav.index=i;inventoryNav.actions=false;inventoryFocus()})});$('card').querySelector('h2')?.insertAdjacentHTML('afterend','<p id="inventoryPadHint" class="inventory-pad-hint" aria-live="polite"></p>');if(!p.bag.length)$('card').querySelector('.baggrid')?.insertAdjacentHTML('beforeend','<p class="muted">鞄は空です。探索で拾った装備がここに並びます。</p>');inventoryFocus()}
const inventoryPanelBase=panel;panel=kind=>{let retain=inventoryNav.open&&paused;inventoryNav.open=kind==='inventory'&&started&&!dead;if(!retain)inventoryNav.index=0;inventoryPanelBase(kind);if(inventoryNav.open)inventorySetup()};
const inventoryCloseBase=closePanel;closePanel=()=>{inventoryNav.open=false;inventoryNav.actions=false;inventoryCloseBase()};
const inventorySettingsBase=showControllerSettings;showControllerSettings=()=>{inventoryNav.open=false;inventorySettingsBase()};
const inventoryMenuBase=padMenu;padMenu=(g,left,right,dt)=>{if(!inventoryNav.open){inventoryMenuBase(g,left,right,dt);return}padCursor.active=false;if(padEdge(g,'map')){let button=$('gearHelpToggle');if(button)toggleGearHelp(button);return}if(padEdge(g,'pause')||padEdge(g,'inventory')){closePanel();return}if(padEdge(g,'back')){inventoryBack();return}let down=i=>!!g.buttons[i]&&(g.buttons[i].pressed||g.buttons[i].value>.5),dx=Number(down(15))-Number(down(14)),dy=Number(down(13))-Number(down(12));if(!dx&&!dy&&left.magnitude>.55){if(Math.abs(left.x)>Math.abs(left.y))dx=Math.sign(left.x);else dy=Math.sign(left.y)}if(dx)dy=0;let direction=dx||dy?dx+','+dy:null;inventoryNav.repeat-=dt;if(direction&&(direction!==inventoryNav.direction||inventoryNav.repeat<=0)){inventoryMove(dx,dy);inventoryNav.repeat=direction===inventoryNav.direction?.14:.36}inventoryNav.direction=direction;if(padEdge(g,'accept'))inventoryAccept()};
// Keyboard access uses the same navigation path, making it useful without a pad too.
addEventListener('keydown',e=>{if(!inventoryNav.open||!paused)return;let dir={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(dir){e.preventDefault();e.stopImmediatePropagation();inventoryMove(...dir)}else if(e.key==='Enter'){e.preventDefault();e.stopImmediatePropagation();if(!e.repeat)inventoryAccept()}else if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();inventoryBack()}},true);

function inventoryJump(bag){let count=$('card').querySelectorAll('.equipment > .gearcard').length;inventoryNav.index=bag&&p.bag.length?count:0;inventoryNav.actions=false;inventoryFocus()}

function inventoryDetailLayout(){let body=$('card').querySelector('.panel-body');if(!body||body.querySelector('.inventory-list'))return;let cards=inventoryCards(),list=document.createElement('div'),detail=document.createElement('aside');list.className='inventory-list';detail.className='inventory-detail';detail.setAttribute('aria-label','選択中の装備');for(let child of Array.from(body.children))list.append(child);cards.forEach((card,index)=>{let pane=document.createElement('section');pane.dataset.inventoryDetail=index;pane.hidden=true;let title=document.createElement('h3');title.textContent=card.querySelector('strong')?.textContent||'未装備';pane.append(title);for(let child of Array.from(card.children))if(child.matches('.mods,.sockets,.socket-upgrades,.crafts,.gear-comparison,p,button'))pane.append(child);detail.append(pane)});body.classList.add('inventory-layout');body.replaceChildren(list,detail);inventoryFocus()}
function inventoryShowDetail(){let panes=$('card').querySelectorAll('[data-inventory-detail]');panes.forEach(pane=>{let visible=+pane.dataset.inventoryDetail===inventoryNav.index;if(visible&&pane.hidden)pane.parentElement.scrollTop=0;pane.hidden=!visible})}
